source='''from math import gcd

def transform(grid):
    h, w = len(grid), len(grid[0])
    eight = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    clue = [(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (0,8)]
    if not eight or not clue:
        return [row[:] for row in grid]
    r0, r1 = min(r for r,c in eight), max(r for r,c in eight)
    c0, c1 = min(c for r,c in eight), max(c for r,c in eight)
    # The large figure is a grid of square, solid 8-colored tiles.
    tile = 0
    for r in range(r0, r1+1):
        n = sum(grid[r][c] == 8 for c in range(c0,c1+1))
        if n: tile = gcd(tile, n)
    for c in range(c0, c1+1):
        n = sum(grid[r][c] == 8 for r in range(r0,r1+1))
        if n: tile = gcd(tile, n)
    if tile == 0:
        return [row[:] for row in grid]
    nr, nc = (r1-r0+1)//tile, (c1-c0+1)//tile
    cells = [[grid[r0+i*tile][c0+j*tile] == 8 for j in range(nc)] for i in range(nr)]
    cr0, cr1 = min(r for r,c in clue), max(r for r,c in clue)
    cc0, cc1 = min(c for r,c in clue), max(c for r,c in clue)
    pattern = [[grid[r][c] for c in range(cc0,cc1+1)] for r in range(cr0,cr1+1)]
    # Turn the small color key clockwise to align it with the large tiled figure.
    rotated = [list(row) for row in zip(*pattern[::-1])]
    if len(rotated) != nr or len(rotated[0]) != nc:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    for i in range(nr):
        for j in range(nc):
            if cells[i][j]:
                color = rotated[i][j]
                if color:
                    for r in range(r0+i*tile, r0+(i+1)*tile):
                        for c in range(c0+j*tile, c0+(j+1)*tile):
                            out[r][c] = color
    return out
'''
